const salesOrder = input['netsuiteFindMatchingSalesOrder'][0];
const refund = input['iterateRefundRequests'][0];
const nsLines = Object.values(salesOrder?.sublists?.item || {});

const matched = [];
const missing = [];

for (const refundItem of refund.items) {
  const nsLine = nsLines.find(line => String(line.itemDisplay || '').trim().toUpperCase() === refundItem.sku);

  if (!nsLine) {
    missing.push(refundItem);
    continue;
  }

  matched.push({
    sku: refundItem.sku,
    itemName: refundItem.name,
    netsuiteItemId: nsLine.item,
    quantity: refundItem.quantity,
    subtotal: refundItem.subtotal
  });
}

return {
  refundId: refund.refundId,
  externalId: refund.externalId,
  shopifyOrderId: refund.shopifyOrderId,
  shopifyOrderName: refund.shopifyOrderName,
  matched,
  missing,
  hasMatchedItems: matched.length > 0
};

const salesOrder = ${JSON.stringify(input?.netsuiteFindMatchingSalesOrder?.[0])};
const rmaData = ${JSON.stringify(input?.mapMatchRefundedItemsToSalesOrderLines?.[0])};

function execute() {
  try {
    const returnAuthRec = record.transform({
      fromType: 'salesorder',
      fromId: salesOrder.id,
      toType: 'returnauthorization',
      isDynamic: true
    });

    returnAuthRec.setValue({ fieldId: 'externalid', value: rmaData.externalId });
    returnAuthRec.setValue({ fieldId: 'custbody_shopify_ord_id', value: rmaData.shopifyOrderName });
    returnAuthRec.setValue({ fieldId: 'memo', value: `Shopify Order ${rmaData.shopifyOrderName}` });
    returnAuthRec.setValue({ fieldId: 'otherrefnum', value: rmaData.shopifyOrderName });

    const matchedItems = rmaData.matched || [];
    let hasValidLine = false;
    const lineCount = returnAuthRec.getLineCount({ sublistId: 'item' });

    for (let i = 0; i < lineCount; i++) {
      const itemId = returnAuthRec.getSublistValue({ sublistId: 'item', fieldId: 'item', line: i });
      const match = matchedItems.find(function (item) { return Number(item.netsuiteItemId) === Number(itemId); });

      returnAuthRec.selectLine({ sublistId: 'item', line: i });

      if (match && Number(match.quantity) > 0) {
        returnAuthRec.setCurrentSublistValue({ sublistId: 'item', fieldId: 'quantity', value: Number(match.quantity) });
        hasValidLine = true;
      } else {
        returnAuthRec.setCurrentSublistValue({ sublistId: 'item', fieldId: 'quantity', value: 0 });
      }

      returnAuthRec.commitLine({ sublistId: 'item' });
    }

    if (!hasValidLine) {
      throw new Error(`No valid refunded item lines were found for Shopify order ${rmaData.shopifyOrderName}.`);
    }

    const returnAuthId = returnAuthRec.save();
    return { id: returnAuthId, externalId: rmaData.externalId };

  } catch (error) {
    return {
      success: false,
      message: error.message,
      stack: error.stack,
      error: error
    };
  }
}

